#!/usr/bin/env bash
# ------------------------------------------------------------------
# 16s_tibagi: commands exactly as recorded in the workflow notes
# Source: Google Docs "Workflow ... (16s_tibagi)", id 1ufDyzBbCMXCKzU2Hxfg0HHhzp8dxFYGIa1HZ7qnhviU
#
# RECORD ONLY - do not run. Paths and file names are the ones used at
# the time, in a WSL working folder that contained the .gb file and an
# NCBI taxdump folder named 'taxdump'. To reproduce the analysis use
#   bash scripts/run_all_targets.sh 16s_tibagi
# ------------------------------------------------------------------

# Step 0 - GenBank query: see config/queries/query_16s_tibagi.txt

# Step 1 - GenBank to FASTA
obiconvert --skip-on-error --genbank -t taxdump 16s_tibagi.gb --fasta-output > 16s_tibagi.fasta

# Step 2 - unique taxids
grep -i -o 'taxid=[0-9]*' 16s_tibagi.fasta | cut -d '=' -f 2 | sort | uniq > 16s_tibagi_taxids.txt

# Step 3 - remove the target species and build the -i list
grep -v '932087' 16s_tibagi_taxids.txt | awk '{printf "-i %s ", $1}'

# Step 4 - ecoPCR database
python /home/diogo/miniconda3/envs/ecoprimers_env/bin/ecoPCRFormat.py --fasta --taxonomy taxdump --name banco_16s_tibagi 16s_tibagi.fasta

# Step 5 - ecoPrimers, primer length N = 20..25 bp (-3 N -O N)
ecoPrimers -d banco_16s_tibagi -l 150 -L 300 -r 932087 -i 1053555 -i 1076518 -i 1123824 -i 1123829 -i 1123834 -i 1123844 -i 1123847 -i 1123849 -i 1123853 -i 1123854 -i 1123874 -i 114109 -i 1150229 -i 1150234 -i 1190664 -i 13013 -i 1349310 -i 1349316 -i 137515 -i 142828 -i 1545849 -i 1566731 -i 162147 -i 1630651 -i 1633027 -i 1633028 -i 1633415 -i 163993 -i 164007 -i 164008 -i 164015 -i 1651834 -i 1651835 -i 1651836 -i 1735002 -i 1740683 -i 1740684 -i 1740685 -i 1740686 -i 1740687 -i 1740688 -i 1740689 -i 1765766 -i 1769426 -i 181452 -i 2023014 -i 2023036 -i 2107549 -i 2175985 -i 2185382 -i 223369 -i 2382282 -i 245748 -i 245769 -i 245770 -i 245775 -i 252593 -i 254544 -i 255577 -i 27695 -i 27720 -i 304017 -i 304048 -i 304083 -i 304084 -i 309911 -i 327003 -i 327006 -i 327007 -i 331123 -i 331128 -i 3359853 -i 337629 -i 3394343 -i 371942 -i 380998 -i 390469 -i 42516 -i 42612 -i 42626 -i 466241 -i 490520 -i 490544 -i 50613 -i 510758 -i 55108 -i 594006 -i 59899 -i 613157 -i 639293 -i 648139 -i 648981 -i 66174 -i 681886 -i 681888 -i 681897 -i 681917 -i 681930 -i 714221 -i 747047 -i 749526 -i 77839 -i 77841 -i 7988 -i 8081 -i 8084 -i 8129 -i 8130 -i 81339 -i 870163 -i 930249 -i 930260 -i 930265 -i 930272 -i 94172 -i 94175 -3 20 -U -O 20 > 16s_tibagi_ecoprimers20.csv
